{
  "call_911_if": [
    {
      "id": "b1",
      "text": "Call 911 if you gain more than 2 pounds in one day or 5 pounds in one week.",
      "sources": ["p1:L26", "p1:L27"]
    },
    {
      "id": "b2",
      "text": "Call 911 if you have trouble breathing while resting or lying flat.",
      "sources": ["p1:L26", "p1:L28", "term:SOB"]
    },
    {
      "id": "b3",
      "text": "Call 911 if chest pain does not go away after three nitroglycerin doses.",
      "sources": ["p1:L26", "p1:L29"]
    },
    {
      "id": "b4",
      "text": "Call 911 if you faint or have a very slow heartbeat.",
      "sources": ["p1:L26", "p1:L30"]
    }
  ]
}
